// Two-layer neural-net training demo.
//
// The target data is generated by a fixed 2-layer teacher network made of two
// 4×4 matrices with a tanh hidden activation and a tanh output activation:
//     y = tanh(W2ᵗ · tanh(W1ᵗ · x))
//
// Three students, all 2-layer with the same two activations, are trained with
// Adam on that data:
//   - dense4 : plain 4×4 · 4×4         (matches the teacher architecture)
//   - sparse : lifted 16×16 · 16×16, only a handful of cells per layer active,
//              positions random at init and moved by grow-and-prune, + L1
//   - dense16: lifted 16×16 · 16×16, every cell trainable (full capacity)
//
// The lifted models wrap the two trainable matrices in a fixed orthonormal
// up-projection U (16×4) and its transpose (down-projection), so all three see
// comparable 4-D data:  pred = tanh( Uᵀ · ( W2 · tanh( W1 · (U·x) ) ) ).

export type Matrix = number[][];
export type Vec = number[];

export const INPUT_DIM = 4;
export const OUTPUT_DIM = 4;
export const DATASET_SIZE = 64;
export const BATCH_SIZE = 8;
export const EPOCHS = 25;
export const LR = 0.04;
const BETA1 = 0.9;
const BETA2 = 0.999;
const ADAM_EPS = 1e-8;
const SEED = 17;
export const SPARSE_DIM = 16;
const SPARSE_ROUTING_SEED = 91;
const SPARSE_L1 = 0.05;
export const ACTIVE_COUNT = 16; // trainable cells per sparse layer
// Low-rank factorization W = A·B uses rank r → 2·dim·r params per layer.
// Pick r so the low-rank param count is as close as possible to the sparse one.
export const LOWRANK_R = Math.max(1, Math.round(ACTIVE_COUNT / (2 * SPARSE_DIM)));

export type Mode = "dense16" | "sparse" | "lowrank";

// params per model (both layers) — used for the parity display
export const PARAM_COUNT: Record<Mode, number> = {
  dense16: 2 * SPARSE_DIM * SPARSE_DIM,
  sparse: 2 * ACTIVE_COUNT,
  lowrank: 2 * (2 * SPARSE_DIM * LOWRANK_R),
};

export interface LayerFrame {
  W: Matrix;
  grad: Matrix;
  m: Matrix;
  v: Matrix;
  active?: [number, number][]; // sparse layers only (dense = all cells)
  grown?: [number, number] | null;
  pruned?: [number, number] | null;
}

export interface Frame {
  step: number;
  epoch: number;
  batchInEpoch: number;
  batchIndices: number[];
  layers: LayerFrame[]; // [layer 1, layer 2]
  dataBatchLoss: number;
  dataFullLoss: number;
  l1Penalty: number;
  batchLoss: number;
  fullLoss: number;
  gradNorm: number;
}

export interface ModelCfg {
  dim: number; // 4 (plain) or 16 (lifted)
  lift: Matrix; // dim × 4
  unlift: Matrix; // 4 × dim
  unliftT: Matrix; // dim × 4  (= transpose(unlift))
  sparse: [boolean, boolean];
}

export interface Simulation {
  frames: Frame[];
  targets: Matrix;
  X: Matrix;
  cfg: ModelCfg;
}

export const MODE_META: Record<
  Mode,
  { badge: string; note: string; targetSub: string; batchSub: string }
> = {
  dense16: {
    badge: "Dense 2-layer: two full 16×16 layers — same architecture as the teacher",
    note: "pred = tanh(Uᵀ · (W₂ · tanh(W₁ · U·x))) with both 16×16 layers fully trainable — the SAME architecture that generated the data, so it can recover the teacher almost exactly. This is the realizable reference (the achievable floor).",
    targetSub: "Generated by a randomly-initialised big dense 2-layer network (this architecture).",
    batchSub: "All cells of both 16×16 layers receive a gradient and an Adam update every step.",
  },
  sparse: {
    badge: `Sparse 2-layer: ${ACTIVE_COUNT} movable cells per layer (grow-and-prune) + L1`,
    note: `Same lifted 2-layer form as the reference, but only ${ACTIVE_COUNT} cells per layer are trainable (random at init). Each epoch the largest-gradient cell of each layer is grown from zero and a near-zero, stable cell is pruned. Can a handful of sparse weights approximate the big dense teacher? (L1 penalty shown separately; excluded from the data-loss metric.)`,
    targetSub: "Generated by a randomly-initialised big dense 2-layer network.",
    batchSub: "Active cells drift via grow-and-prune; gradients backprop through both tanh activations, with an L1 term on active weights.",
  },
  lowrank: {
    badge: `Low-rank 2-layer: each layer W = A·B, rank ${LOWRANK_R} — parameter-matched to sparse`,
    note: `Same lifted 2-layer form, but each 16×16 layer is factorized as W = A·B with rank ${LOWRANK_R} (A is 16×${LOWRANK_R}, B is ${LOWRANK_R}×16). Parameter count is matched to the sparse model, so this is the head-to-head: does low-rank or sparse structure approximate a random big dense network better at equal budget?`,
    targetSub: "Generated by a randomly-initialised big dense 2-layer network.",
    batchSub: "Gradients flow to the factors A and B (dA = gW·Bᵀ, dB = Aᵀ·gW); the panels show the effective weight W = A·B.",
  },
};

// ---------- rng / math helpers ----------

function mulberry32(a: number) {
  return function () {
    let t = (a += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randn(rng: () => number): number {
  let u = 0,
    v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
}

function cloneMatrix(m: Matrix): Matrix {
  return m.map((row) => row.slice());
}

function matVec(M: Matrix, v: Vec): Vec {
  return M.map((row) => row.reduce((sum, w, i) => sum + w * v[i], 0));
}

function transposeMatrix(M: Matrix): Matrix {
  return M[0].map((_, j) => M.map((row) => row[j]));
}

function zeroMatrix(rows: number, cols = rows): Matrix {
  return Array.from({ length: rows }, () => Array(cols).fill(0));
}

function mse(pred: Vec, target: Vec): number {
  let s = 0;
  for (let i = 0; i < pred.length; i++) {
    const d = pred[i] - target[i];
    s += d * d;
  }
  return s / pred.length;
}

export function maxAbs(arr: Vec): number {
  return Math.max(...arr.map((v) => Math.abs(v)), 1e-9);
}

export function flatten2D(m: Matrix): Vec {
  return m.flat();
}

export function msePublic(pred: Vec, target: Vec): number {
  return mse(pred, target);
}

const ACT = (v: number) => Math.tanh(v); // hidden and output activation (tanh)

function shuffleIndices(n: number, rng: () => number): number[] {
  const arr = Array.from({ length: n }, (_, i) => i);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function createEpochOrders(): number[][] {
  const rng = mulberry32(SEED + 101);
  const orders: number[][] = [];
  for (let epoch = 0; epoch < EPOCHS; epoch++) orders.push(shuffleIndices(DATASET_SIZE, rng));
  return orders;
}

function matMul(A: Matrix, B: Matrix): Matrix {
  const rows = A.length;
  const inner = B.length;
  const cols = B[0].length;
  const out = Array.from({ length: rows }, () => Array(cols).fill(0));
  for (let i = 0; i < rows; i++)
    for (let k = 0; k < inner; k++) {
      const a = A[i][k];
      if (a === 0) continue;
      for (let j = 0; j < cols; j++) out[i][j] += a * B[k][j];
    }
  return out;
}

// ---------- lift (orthonormal up-projection U, 16×4) ----------

function orthonormalizeColumns(matrix: Matrix): Matrix | null {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const q = Array.from({ length: rows }, () => Array(cols).fill(0));
  for (let col = 0; col < cols; col++) {
    const v = matrix.map((row) => row[col]);
    for (let prev = 0; prev < col; prev++) {
      const qprev = q.map((row) => row[prev]);
      let proj = 0;
      for (let i = 0; i < rows; i++) proj += v[i] * qprev[i];
      for (let i = 0; i < rows; i++) v[i] -= proj * qprev[i];
    }
    let norm = 0;
    for (let i = 0; i < rows; i++) norm += v[i] * v[i];
    norm = Math.sqrt(norm);
    if (!isFinite(norm) || norm < 1e-12) return null;
    for (let i = 0; i < rows; i++) q[i][col] = v[i] / norm;
  }
  return q;
}

function buildLift(rng: () => number): Matrix {
  let up: Matrix | null = null;
  while (!up) {
    const raw = Array.from({ length: SPARSE_DIM }, () =>
      Array.from({ length: INPUT_DIM }, () => randn(rng))
    );
    up = orthonormalizeColumns(raw);
  }
  return up;
}

// ---------- forward / backward for the 2-layer model ----------

interface Forward {
  z: Vec;
  a1: Vec;
  h1: Vec;
  a2: Vec;
  u: Vec;
  pred: Vec;
}

export function forwardModel(W1: Matrix, W2: Matrix, x: Vec, cfg: ModelCfg): Forward {
  const z = matVec(cfg.lift, x); // lift (identity for dense4)
  const a1 = matVec(W1, z);
  const h1 = a1.map(ACT); // hidden activation
  const a2 = matVec(W2, h1);
  const u = matVec(cfg.unlift, a2); // unlift (identity for dense4)
  const pred = u.map(ACT); // output activation
  return { z, a1, h1, a2, u, pred };
}

// Dense gradients for both layers + mean data loss for a mini-batch.
function grads2(
  batchIndices: number[],
  X: Matrix,
  Y: Matrix,
  W1: Matrix,
  W2: Matrix,
  cfg: ModelCfg
): { gW1: Matrix; gW2: Matrix; dataLoss: number } {
  const dim = cfg.dim;
  const gW1 = zeroMatrix(dim);
  const gW2 = zeroMatrix(dim);
  let dataLoss = 0;
  const scale = 2 / (batchIndices.length * OUTPUT_DIM);
  const W2T = transposeMatrix(W2);
  for (const idx of batchIndices) {
    const { z, h1, pred } = forwardModel(W1, W2, X[idx], cfg);
    dataLoss += mse(pred, Y[idx]);
    // output: pred = tanh(u); ∂L/∂u = (pred − y) ⊙ (1 − pred²)
    const du = pred.map((p, i) => (p - Y[idx][i]) * (1 - p * p));
    const da2 = matVec(cfg.unliftT, du); // ∂L/∂a2  (dim)
    for (let i = 0; i < dim; i++) for (let j = 0; j < dim; j++) gW2[i][j] += scale * da2[i] * h1[j];
    const dh1 = matVec(W2T, da2); // ∂L/∂h1
    const da1 = dh1.map((d, i) => d * (1 - h1[i] * h1[i])); // through hidden tanh
    for (let i = 0; i < dim; i++) for (let j = 0; j < dim; j++) gW1[i][j] += scale * da1[i] * z[j];
  }
  return { gW1, gW2, dataLoss: dataLoss / batchIndices.length };
}

function fullLoss2(W1: Matrix, W2: Matrix, X: Matrix, Y: Matrix, cfg: ModelCfg): number {
  let total = 0;
  for (let n = 0; n < X.length; n++) total += mse(forwardModel(W1, W2, X[n], cfg).pred, Y[n]);
  return total / X.length;
}

// ---------- grow-and-prune (per sparse layer) ----------

function chooseGrow(grad: Matrix, activeSet: Set<string>, dim: number): [number, number] | null {
  let best: [number, number] | null = null;
  let bestScore = -1;
  for (let i = 0; i < dim; i++)
    for (let j = 0; j < dim; j++) {
      if (activeSet.has(`${i}:${j}`)) continue;
      const s = Math.abs(grad[i][j]);
      if (s > bestScore) {
        bestScore = s;
        best = [i, j];
      }
    }
  return best;
}

const PRUNE_W_FRAC = 0.35;
const PRUNE_M_FRAC = 0.4;
const PRUNE_G_FRAC = 0.6;

interface PruneChoice {
  pos: [number, number];
  wRatio: number;
  mRatio: number;
  gRatio: number;
}

function choosePrune(
  W: Matrix,
  m: Matrix,
  grad: Matrix,
  active: [number, number][]
): PruneChoice | null {
  let maxW = 1e-9;
  let maxM = 1e-9;
  let maxG = 1e-9;
  for (const [r, c] of active) {
    maxW = Math.max(maxW, Math.abs(W[r][c]));
    maxM = Math.max(maxM, Math.abs(m[r][c]));
    maxG = Math.max(maxG, Math.abs(grad[r][c]));
  }
  let best: PruneChoice | null = null;
  let bestScore = Infinity;
  for (const [r, c] of active) {
    const wRatio = Math.abs(W[r][c]) / maxW;
    const mRatio = Math.abs(m[r][c]) / maxM;
    const gRatio = Math.abs(grad[r][c]) / maxG;
    const dead = wRatio + mRatio + gRatio;
    if (dead < bestScore) {
      bestScore = dead;
      best = { pos: [r, c], wRatio, mRatio, gRatio };
    }
  }
  return best;
}

function isSafeToPrune(p: PruneChoice): boolean {
  return p.wRatio < PRUNE_W_FRAC && p.mRatio < PRUNE_M_FRAC && p.gRatio < PRUNE_G_FRAC;
}

function sparseL1Penalty(W: Matrix, active: [number, number][]): number {
  let sumAbs = 0;
  for (const [r, c] of active) sumAbs += Math.abs(W[r][c]);
  return SPARSE_L1 * (sumAbs / active.length);
}

// ---------- unified 2-layer trainer ----------

interface Layer {
  W: Matrix;
  m: Matrix;
  v: Matrix;
  sparse: boolean;
  activeSet: Set<string>;
  activeList: [number, number][];
}

function makeLayer(dim: number, sparse: boolean, W: Matrix): Layer {
  const activeList: [number, number][] = [];
  const activeSet = new Set<string>();
  for (let i = 0; i < dim; i++)
    for (let j = 0; j < dim; j++) {
      if (!sparse || Math.abs(W[i][j]) > 1e-12) {
        activeList.push([i, j]);
        activeSet.add(`${i}:${j}`);
      }
    }
  return { W: cloneMatrix(W), m: zeroMatrix(dim), v: zeroMatrix(dim), sparse, activeSet, activeList };
}

function applyGrowPrune(
  layer: Layer,
  grad: Matrix,
  dim: number
): { grown: [number, number] | null; pruned: [number, number] | null } {
  if (!layer.sparse) return { grown: null, pruned: null };
  const grow = chooseGrow(grad, layer.activeSet, dim);
  const prune = choosePrune(layer.W, layer.m, grad, layer.activeList);
  if (
    grow &&
    prune &&
    isSafeToPrune(prune) &&
    Math.abs(grad[grow[0]][grow[1]]) > Math.abs(grad[prune.pos[0]][prune.pos[1]])
  ) {
    const [gr, gc] = grow;
    const [pr, pc] = prune.pos;
    layer.activeSet.delete(`${pr}:${pc}`);
    layer.activeSet.add(`${gr}:${gc}`);
    layer.activeList = layer.activeList.filter(([a, b]) => !(a === pr && b === pc));
    layer.activeList.push([gr, gc]);
    layer.W[pr][pc] = 0;
    layer.m[pr][pc] = 0;
    layer.v[pr][pc] = 0;
    layer.W[gr][gc] = 0; // grow at zero: prediction unchanged at the swap
    layer.m[gr][gc] = 0;
    layer.v[gr][gc] = 0;
    return { grown: grow, pruned: prune.pos };
  }
  return { grown: null, pruned: null };
}

function buildTwoLayerFrames(
  X: Matrix,
  Y: Matrix,
  epochOrders: number[][],
  cfg: ModelCfg,
  init1: Matrix,
  init2: Matrix
): Frame[] {
  const dim = cfg.dim;
  const L1 = makeLayer(dim, cfg.sparse[0], init1);
  const L2 = makeLayer(dim, cfg.sparse[1], init2);
  const frames: Frame[] = [];
  let step = 0;

  const processLayer = (
    layer: Layer,
    gW: Matrix,
    adamStep: number,
    grown: [number, number] | null,
    pruned: [number, number] | null
  ): { frame: LayerFrame; gradSq: number } => {
    if (layer.sparse) {
      const s = SPARSE_L1 / layer.activeList.length;
      for (const [r, c] of layer.activeList) gW[r][c] += s * Math.sign(layer.W[r][c]);
    }
    const beta1Pow = Math.pow(BETA1, adamStep);
    const beta2Pow = Math.pow(BETA2, adamStep);
    const nextM = cloneMatrix(layer.m);
    const nextV = cloneMatrix(layer.v);
    let gradSq = 0;
    for (const [r, c] of layer.activeList) {
      const g = gW[r][c];
      nextM[r][c] = BETA1 * nextM[r][c] + (1 - BETA1) * g;
      nextV[r][c] = BETA2 * nextV[r][c] + (1 - BETA2) * g * g;
      gradSq += g * g;
    }
    const frame: LayerFrame = {
      W: cloneMatrix(layer.W),
      grad: cloneMatrix(gW),
      m: cloneMatrix(nextM),
      v: cloneMatrix(nextV),
      active: layer.sparse ? layer.activeList.map(([r, c]) => [r, c] as [number, number]) : undefined,
      grown,
      pruned,
    };
    for (const [r, c] of layer.activeList) {
      const mHat = nextM[r][c] / (1 - beta1Pow);
      const vHat = nextV[r][c] / (1 - beta2Pow);
      layer.W[r][c] -= (LR * mHat) / (Math.sqrt(vHat) + ADAM_EPS);
    }
    layer.m = nextM;
    layer.v = nextV;
    return { frame, gradSq };
  };

  for (let epoch = 0; epoch < EPOCHS; epoch++) {
    const order = epochOrders[epoch];
    for (let batchStart = 0; batchStart < DATASET_SIZE; batchStart += BATCH_SIZE) {
      const batchIndices = order.slice(batchStart, batchStart + BATCH_SIZE);

      let g1: { grown: [number, number] | null; pruned: [number, number] | null } = {
        grown: null,
        pruned: null,
      };
      let g2 = g1;
      if (epoch >= 1 && batchStart === 0) {
        const probe = grads2(batchIndices, X, Y, L1.W, L2.W, cfg);
        g1 = applyGrowPrune(L1, probe.gW1, dim);
        g2 = applyGrowPrune(L2, probe.gW2, dim);
      }

      const { gW1, gW2, dataLoss } = grads2(batchIndices, X, Y, L1.W, L2.W, cfg);
      const dataFullLoss = fullLoss2(L1.W, L2.W, X, Y, cfg);
      let l1Penalty = 0;
      if (L1.sparse) l1Penalty += sparseL1Penalty(L1.W, L1.activeList);
      if (L2.sparse) l1Penalty += sparseL1Penalty(L2.W, L2.activeList);

      const adamStep = step + 1;
      const r1 = processLayer(L1, gW1, adamStep, g1.grown, g1.pruned);
      const r2 = processLayer(L2, gW2, adamStep, g2.grown, g2.pruned);

      frames.push({
        step,
        epoch,
        batchInEpoch: batchStart / BATCH_SIZE,
        batchIndices,
        layers: [r1.frame, r2.frame],
        dataBatchLoss: dataLoss,
        dataFullLoss,
        l1Penalty,
        batchLoss: dataLoss + l1Penalty,
        fullLoss: dataFullLoss + l1Penalty,
        gradNorm: Math.sqrt(r1.gradSq + r2.gradSq),
      });
      step += 1;
    }
  }
  return frames;
}

// ---------- cheap sparse trainer ----------
// Never materializes the full n² gradient. For each layer it computes only the
// k active-cell gradients (for the Adam update / prune), and for growth it uses
// an approximate top-p × top-q candidate search: the batch gradient is
// gW = Σ_b da_b ⊗ input_b, so |gW[i][j]| is large when row i (error) and column
// j (input activation) are both large — score only the top rows × top columns.
const GROW_TOPK = 4; // top rows / cols to consider as grow candidates

function buildSparseFrames(
  X: Matrix,
  Y: Matrix,
  epochOrders: number[][],
  cfg: ModelCfg,
  init1: Matrix,
  init2: Matrix
): Frame[] {
  const dim = cfg.dim;
  const W1 = cloneMatrix(init1);
  const W2 = cloneMatrix(init2);
  const m1 = zeroMatrix(dim);
  const v1 = zeroMatrix(dim);
  const m2 = zeroMatrix(dim);
  const v2 = zeroMatrix(dim);
  const aset1 = new Set<string>();
  const aset2 = new Set<string>();
  let alist1: [number, number][] = [];
  let alist2: [number, number][] = [];
  for (let i = 0; i < dim; i++)
    for (let j = 0; j < dim; j++) {
      if (Math.abs(init1[i][j]) > 1e-12) {
        aset1.add(`${i}:${j}`);
        alist1.push([i, j]);
      }
      if (Math.abs(init2[i][j]) > 1e-12) {
        aset2.add(`${i}:${j}`);
        alist2.push([i, j]);
      }
    }
  const frames: Frame[] = [];
  let step = 0;

  const topIdx = (mags: number[], k: number): number[] =>
    mags.map((_, i) => i).sort((a, b) => mags[b] - mags[a]).slice(0, k);

  // One batch: per-example errors/inputs + the k active-cell gradients only.
  const collect = (batchIndices: number[], active1: [number, number][], active2: [number, number][]) => {
    const B = batchIndices.length;
    const scale = 2 / (B * OUTPUT_DIM);
    const DA1: Vec[] = [];
    const Z: Vec[] = [];
    const DA2: Vec[] = [];
    const H1: Vec[] = [];
    let dataLoss = 0;
    const W2T = transposeMatrix(W2);
    for (const idx of batchIndices) {
      const z = matVec(cfg.lift, X[idx]);
      const h1 = matVec(W1, z).map(ACT);
      const a2 = matVec(W2, h1);
      const pred = matVec(cfg.unlift, a2).map(ACT);
      dataLoss += mse(pred, Y[idx]);
      const du = pred.map((p, i) => (p - Y[idx][i]) * (1 - p * p));
      const da2 = matVec(cfg.unliftT, du);
      const dh1 = matVec(W2T, da2); // sparse in practice (only active W2 cells)
      const da1 = dh1.map((d, i) => d * (1 - h1[i] * h1[i]));
      DA1.push(da1);
      Z.push(z);
      DA2.push(da2);
      H1.push(h1);
    }
    const gW1 = zeroMatrix(dim);
    const gW2 = zeroMatrix(dim);
    for (const [i, j] of active1) {
      let s = 0;
      for (let b = 0; b < B; b++) s += DA1[b][i] * Z[b][j];
      gW1[i][j] = scale * s;
    }
    for (const [i, j] of active2) {
      let s = 0;
      for (let b = 0; b < B; b++) s += DA2[b][i] * H1[b][j];
      gW2[i][j] = scale * s;
    }
    return { DA1, Z, DA2, H1, gW1, gW2, dataLoss: dataLoss / B, scale };
  };

  // Approximate grow: best inactive cell among top-p error rows × top-q input cols.
  const growApprox = (
    DA: Vec[],
    INP: Vec[],
    aset: Set<string>,
    scale: number
  ): { pos: [number, number]; mag: number } | null => {
    const B = DA.length;
    const rowMag = Array(dim).fill(0);
    const colMag = Array(dim).fill(0);
    for (let b = 0; b < B; b++)
      for (let i = 0; i < dim; i++) {
        rowMag[i] += DA[b][i] * DA[b][i];
        colMag[i] += INP[b][i] * INP[b][i];
      }
    const rows = topIdx(rowMag, GROW_TOPK);
    const cols = topIdx(colMag, GROW_TOPK);
    let best: [number, number] | null = null;
    let bestMag = -1;
    for (const i of rows)
      for (const j of cols) {
        if (aset.has(`${i}:${j}`)) continue;
        let s = 0;
        for (let b = 0; b < B; b++) s += DA[b][i] * INP[b][j];
        const mag = Math.abs(scale * s);
        if (mag > bestMag) {
          bestMag = mag;
          best = [i, j];
        }
      }
    return best ? { pos: best, mag: bestMag } : null;
  };

  const doSwap = (
    W: Matrix,
    m: Matrix,
    v: Matrix,
    aset: Set<string>,
    alist: [number, number][],
    prune: [number, number],
    grow: [number, number]
  ): [number, number][] => {
    const [pr, pc] = prune;
    const [gr, gc] = grow;
    aset.delete(`${pr}:${pc}`);
    aset.add(`${gr}:${gc}`);
    W[pr][pc] = 0;
    m[pr][pc] = 0;
    v[pr][pc] = 0;
    W[gr][gc] = 0;
    m[gr][gc] = 0;
    v[gr][gc] = 0;
    return alist.filter(([a, b]) => !(a === pr && b === pc)).concat([[gr, gc]]);
  };

  const updateLayer = (
    W: Matrix,
    m: Matrix,
    v: Matrix,
    gW: Matrix,
    alist: [number, number][],
    b1p: number,
    b2p: number,
    grown: [number, number] | null,
    pruned: [number, number] | null
  ): { frame: LayerFrame; gradSq: number } => {
    let gradSq = 0;
    for (const [r, c] of alist) {
      const g = gW[r][c];
      m[r][c] = BETA1 * m[r][c] + (1 - BETA1) * g;
      v[r][c] = BETA2 * v[r][c] + (1 - BETA2) * g * g;
      gradSq += g * g;
    }
    const frame: LayerFrame = {
      W: cloneMatrix(W),
      grad: cloneMatrix(gW),
      m: cloneMatrix(m),
      v: zeroMatrix(dim),
      active: alist.map(([r, c]) => [r, c] as [number, number]),
      grown,
      pruned,
    };
    for (const [r, c] of alist) {
      const mHat = m[r][c] / (1 - b1p);
      const vHat = v[r][c] / (1 - b2p);
      W[r][c] -= (LR * mHat) / (Math.sqrt(vHat) + ADAM_EPS);
    }
    return { frame, gradSq };
  };

  for (let epoch = 0; epoch < EPOCHS; epoch++) {
    const order = epochOrders[epoch];
    for (let batchStart = 0; batchStart < DATASET_SIZE; batchStart += BATCH_SIZE) {
      const batchIndices = order.slice(batchStart, batchStart + BATCH_SIZE);
      let grown1: [number, number] | null = null;
      let pruned1: [number, number] | null = null;
      let grown2: [number, number] | null = null;
      let pruned2: [number, number] | null = null;

      if (epoch >= 1 && batchStart === 0) {
        const probe = collect(batchIndices, alist1, alist2);
        const g1 = growApprox(probe.DA1, probe.Z, aset1, probe.scale);
        const p1 = choosePrune(W1, m1, probe.gW1, alist1);
        if (g1 && p1 && isSafeToPrune(p1) && g1.mag > Math.abs(probe.gW1[p1.pos[0]][p1.pos[1]])) {
          alist1 = doSwap(W1, m1, v1, aset1, alist1, p1.pos, g1.pos);
          grown1 = g1.pos;
          pruned1 = p1.pos;
        }
        const g2 = growApprox(probe.DA2, probe.H1, aset2, probe.scale);
        const p2 = choosePrune(W2, m2, probe.gW2, alist2);
        if (g2 && p2 && isSafeToPrune(p2) && g2.mag > Math.abs(probe.gW2[p2.pos[0]][p2.pos[1]])) {
          alist2 = doSwap(W2, m2, v2, aset2, alist2, p2.pos, g2.pos);
          grown2 = g2.pos;
          pruned2 = p2.pos;
        }
      }

      const cur = collect(batchIndices, alist1, alist2);
      const dataFullLoss = fullLoss2(W1, W2, X, Y, cfg);
      const l1Penalty = sparseL1Penalty(W1, alist1) + sparseL1Penalty(W2, alist2);
      const s1 = SPARSE_L1 / alist1.length;
      const s2 = SPARSE_L1 / alist2.length;
      for (const [r, c] of alist1) cur.gW1[r][c] += s1 * Math.sign(W1[r][c]);
      for (const [r, c] of alist2) cur.gW2[r][c] += s2 * Math.sign(W2[r][c]);

      const adamStep = step + 1;
      const b1p = Math.pow(BETA1, adamStep);
      const b2p = Math.pow(BETA2, adamStep);
      const r1 = updateLayer(W1, m1, v1, cur.gW1, alist1, b1p, b2p, grown1, pruned1);
      const r2 = updateLayer(W2, m2, v2, cur.gW2, alist2, b1p, b2p, grown2, pruned2);

      frames.push({
        step,
        epoch,
        batchInEpoch: batchStart / BATCH_SIZE,
        batchIndices,
        layers: [r1.frame, r2.frame],
        dataBatchLoss: cur.dataLoss,
        dataFullLoss,
        l1Penalty,
        batchLoss: cur.dataLoss + l1Penalty,
        fullLoss: dataFullLoss + l1Penalty,
        gradNorm: Math.sqrt(r1.gradSq + r2.gradSq),
      });
      step += 1;
    }
  }
  return frames;
}

// ---------- low-rank trainer (each layer W = A·B) ----------

// In-place Adam update of a parameter matrix given its gradient + moments.
function adamUpdate(
  W: Matrix,
  grad: Matrix,
  m: Matrix,
  v: Matrix,
  beta1Pow: number,
  beta2Pow: number
): number {
  let gradSq = 0;
  for (let i = 0; i < W.length; i++)
    for (let j = 0; j < W[0].length; j++) {
      const g = grad[i][j];
      gradSq += g * g;
      m[i][j] = BETA1 * m[i][j] + (1 - BETA1) * g;
      v[i][j] = BETA2 * v[i][j] + (1 - BETA2) * g * g;
      const mHat = m[i][j] / (1 - beta1Pow);
      const vHat = v[i][j] / (1 - beta2Pow);
      W[i][j] -= (LR * mHat) / (Math.sqrt(vHat) + ADAM_EPS);
    }
  return gradSq;
}

function buildLowRankFrames(
  X: Matrix,
  Y: Matrix,
  epochOrders: number[][],
  cfg: ModelCfg,
  A1: Matrix,
  B1: Matrix,
  A2: Matrix,
  B2: Matrix
): Frame[] {
  const dim = cfg.dim;
  const frames: Frame[] = [];
  let step = 0;
  // Adam moments for each factor.
  const mA1 = zeroMatrix(dim, A1[0].length);
  const vA1 = zeroMatrix(dim, A1[0].length);
  const mB1 = zeroMatrix(B1.length, dim);
  const vB1 = zeroMatrix(B1.length, dim);
  const mA2 = zeroMatrix(dim, A2[0].length);
  const vA2 = zeroMatrix(dim, A2[0].length);
  const mB2 = zeroMatrix(B2.length, dim);
  const vB2 = zeroMatrix(B2.length, dim);
  // display-only EMA of the effective-weight gradient (a "momentum" view)
  const mEff1 = zeroMatrix(dim);
  const mEff2 = zeroMatrix(dim);

  for (let epoch = 0; epoch < EPOCHS; epoch++) {
    const order = epochOrders[epoch];
    for (let batchStart = 0; batchStart < DATASET_SIZE; batchStart += BATCH_SIZE) {
      const batchIndices = order.slice(batchStart, batchStart + BATCH_SIZE);
      const W1 = matMul(A1, B1); // effective 16×16
      const W2 = matMul(A2, B2);
      const { gW1, gW2, dataLoss } = grads2(batchIndices, X, Y, W1, W2, cfg);
      const dataFullLoss = fullLoss2(W1, W2, X, Y, cfg);

      // effective-weight gradient → factor gradients
      const dA1 = matMul(gW1, transposeMatrix(B1));
      const dB1 = matMul(transposeMatrix(A1), gW1);
      const dA2 = matMul(gW2, transposeMatrix(B2));
      const dB2 = matMul(transposeMatrix(A2), gW2);

      // momentum view (EMA of effective gradient)
      for (let i = 0; i < dim; i++)
        for (let j = 0; j < dim; j++) {
          mEff1[i][j] = BETA1 * mEff1[i][j] + (1 - BETA1) * gW1[i][j];
          mEff2[i][j] = BETA1 * mEff2[i][j] + (1 - BETA1) * gW2[i][j];
        }

      const l1: LayerFrame = {
        W: W1.map((r) => r.slice()),
        grad: gW1.map((r) => r.slice()),
        m: mEff1.map((r) => r.slice()),
        v: zeroMatrix(dim),
        grown: null,
        pruned: null,
      };
      const l2: LayerFrame = {
        W: W2.map((r) => r.slice()),
        grad: gW2.map((r) => r.slice()),
        m: mEff2.map((r) => r.slice()),
        v: zeroMatrix(dim),
        grown: null,
        pruned: null,
      };

      const adamStep = step + 1;
      const b1p = Math.pow(BETA1, adamStep);
      const b2p = Math.pow(BETA2, adamStep);
      const gs =
        adamUpdate(A1, dA1, mA1, vA1, b1p, b2p) +
        adamUpdate(B1, dB1, mB1, vB1, b1p, b2p) +
        adamUpdate(A2, dA2, mA2, vA2, b1p, b2p) +
        adamUpdate(B2, dB2, mB2, vB2, b1p, b2p);

      frames.push({
        step,
        epoch,
        batchInEpoch: batchStart / BATCH_SIZE,
        batchIndices,
        layers: [l1, l2],
        dataBatchLoss: dataLoss,
        dataFullLoss,
        l1Penalty: 0,
        batchLoss: dataLoss,
        fullLoss: dataFullLoss,
        gradNorm: Math.sqrt(gs),
      });
      step += 1;
    }
  }
  return frames;
}

// ---------- random initialisers ----------

function randomDense(rng: () => number, dim: number, scale: number): Matrix {
  return Array.from({ length: dim }, () =>
    Array.from({ length: dim }, () => randn(rng) * scale)
  );
}

function randomSparse(rng: () => number, dim: number, count: number, scale: number): Matrix {
  const W = zeroMatrix(dim);
  const used = new Set<string>();
  let placed = 0;
  while (placed < count) {
    const r = Math.floor(rng() * dim);
    const c = Math.floor(rng() * dim);
    const key = `${r}:${c}`;
    if (used.has(key)) continue;
    used.add(key);
    W[r][c] = randn(rng) * scale;
    placed += 1;
  }
  return W;
}

function randomFactor(rng: () => number, rows: number, cols: number, scale: number): Matrix {
  return Array.from({ length: rows }, () => Array.from({ length: cols }, () => randn(rng) * scale));
}

// Build all three simulations once. Deterministic (seeded).
// The target data is generated by a randomly-initialised BIG DENSE 2-layer
// network (the same lifted architecture as the dense16 tab), so we can measure
// how well the low-parameter sparse and low-rank students approximate it.
export function buildSimulations(): Record<Mode, Simulation> {
  const U = buildLift(mulberry32(SEED + SPARSE_ROUTING_SEED)); // 16×4
  const UT = transposeMatrix(U); // 4×16 (down-projection)
  const cfg: ModelCfg = {
    dim: SPARSE_DIM,
    lift: U,
    unlift: UT,
    unliftT: transposeMatrix(UT), // = U (16×4)
    sparse: [false, false],
  };
  const sparseCfg: ModelCfg = { ...cfg, sparse: [true, true] };

  // --- teacher: big dense random 2-layer net → synthetic data ---
  const tRng = mulberry32(SEED + 777);
  const W1t = randomDense(tRng, SPARSE_DIM, 0.5);
  const W2t = randomDense(tRng, SPARSE_DIM, 0.5);
  const xRng = mulberry32(SEED);
  const X = Array.from({ length: DATASET_SIZE }, () =>
    Array.from({ length: INPUT_DIM }, () => randn(xRng) * 1.0)
  );
  const Y = X.map((x) => forwardModel(W1t, W2t, x, cfg).pred);
  const epochOrders = createEpochOrders();

  // --- students ---
  const d16 = mulberry32(SEED + 33);
  const sp = mulberry32(SEED + 22);
  const lr = mulberry32(SEED + 44);
  const r = LOWRANK_R;
  const factorScale = Math.pow(0.1225 / r, 0.25); // keeps effective W ≈ 0.35 scale

  return {
    dense16: {
      frames: buildTwoLayerFrames(
        X,
        Y,
        epochOrders,
        cfg,
        randomDense(d16, SPARSE_DIM, 0.35),
        randomDense(d16, SPARSE_DIM, 0.35)
      ),
      targets: Y,
      X,
      cfg,
    },
    sparse: {
      frames: buildSparseFrames(
        X,
        Y,
        epochOrders,
        sparseCfg,
        randomSparse(sp, SPARSE_DIM, ACTIVE_COUNT, 0.6),
        randomSparse(sp, SPARSE_DIM, ACTIVE_COUNT, 0.6)
      ),
      targets: Y,
      X,
      cfg: sparseCfg,
    },
    lowrank: {
      frames: buildLowRankFrames(
        X,
        Y,
        epochOrders,
        cfg,
        randomFactor(lr, SPARSE_DIM, r, factorScale),
        randomFactor(lr, r, SPARSE_DIM, factorScale),
        randomFactor(lr, SPARSE_DIM, r, factorScale),
        randomFactor(lr, r, SPARSE_DIM, factorScale)
      ),
      targets: Y,
      X,
      cfg,
    },
  };
}
